func userFromRecord(rec protocol.Record) User {
	m := User{}
	m.ID = recString(rec, "id")
	m.Username = recString(rec, "username")
	m.DisplayName = recStringPtr(rec, "display_name")
	m.PasswordHash = recString(rec, "password_hash")
	m.Email = recStringPtr(rec, "email")
	m.CreatedAt = recInt64(rec, "created_at")
	if kids, ok := rec["sessions"].([]any); ok {
		for _, k := range kids {
			if child, ok := k.(map[string]any); ok {
				m.Sessions = append(m.Sessions, sessionFromRecord(child))
			}
		}
	}
	if kids, ok := rec["team_members"].([]any); ok {
		for _, k := range kids {
			if child, ok := k.(map[string]any); ok {
				m.TeamMembers = append(m.TeamMembers, teamMemberFromRecord(child))
			}
		}
	}
	if kids, ok := rec["tasks_by_assignee"].([]any); ok {
		for _, k := range kids {
			if child, ok := k.(map[string]any); ok {
				m.TasksByAssignee = append(m.TasksByAssignee, taskFromRecord(child))
			}
		}
	}
	if kids, ok := rec["tasks_by_creator"].([]any); ok {
		for _, k := range kids {
			if child, ok := k.(map[string]any); ok {
				m.TasksByCreator = append(m.TasksByCreator, taskFromRecord(child))
			}
		}
	}
	if kids, ok := rec["comments"].([]any); ok {
		for _, k := range kids {
			if child, ok := k.(map[string]any); ok {
				m.Comments = append(m.Comments, commentFromRecord(child))
			}
		}
	}
	return m
}

