func teamFromRecord(rec protocol.Record) Team {
	m := Team{}
	m.ID = recString(rec, "id")
	m.Name = recString(rec, "name")
	m.CreatedAt = recInt64(rec, "created_at")
	if kids, ok := rec["team_members"].([]any); ok {
		for _, k := range kids {
			if child, ok := k.(map[string]any); ok {
				m.TeamMembers = append(m.TeamMembers, teamMemberFromRecord(child))
			}
		}
	}
	if kids, ok := rec["boards"].([]any); ok {
		for _, k := range kids {
			if child, ok := k.(map[string]any); ok {
				m.Boards = append(m.Boards, boardFromRecord(child))
			}
		}
	}
	if kids, ok := rec["labels"].([]any); ok {
		for _, k := range kids {
			if child, ok := k.(map[string]any); ok {
				m.Labels = append(m.Labels, labelFromRecord(child))
			}
		}
	}
	return m
}

