func taskFromRecord(rec protocol.Record) Task {
	m := Task{}
	m.ID = recString(rec, "id")
	m.BoardID = recString(rec, "board_id")
	m.Title = recString(rec, "title")
	m.Description = recStringPtr(rec, "description")
	m.Status = recString(rec, "status")
	m.Priority = recInt64(rec, "priority")
	m.Estimate = recFloat64Ptr(rec, "estimate")
	m.AssigneeID = recStringPtr(rec, "assignee_id")
	m.CreatorID = recString(rec, "creator_id")
	m.ParentID = recStringPtr(rec, "parent_id")
	m.DueAt = recInt64Ptr(rec, "due_at")
	m.CreatedAt = recInt64(rec, "created_at")
	if parent, ok := rec["board"].(map[string]any); ok {
		v := boardFromRecord(parent)
		m.Board = &v
	}
	if parent, ok := rec["assignee"].(map[string]any); ok {
		v := userFromRecord(parent)
		m.Assignee = &v
	}
	if parent, ok := rec["creator"].(map[string]any); ok {
		v := userFromRecord(parent)
		m.Creator = &v
	}
	if parent, ok := rec["parent"].(map[string]any); ok {
		v := taskFromRecord(parent)
		m.Parent = &v
	}
	if kids, ok := rec["tasks"].([]any); ok {
		for _, k := range kids {
			if child, ok := k.(map[string]any); ok {
				m.Tasks = append(m.Tasks, taskFromRecord(child))
			}
		}
	}
	if kids, ok := rec["comments"].([]any); ok {
		for _, k := range kids {
			if child, ok := k.(map[string]any); ok {
				m.Comments = append(m.Comments, commentFromRecord(child))
			}
		}
	}
	if kids, ok := rec["task_labels"].([]any); ok {
		for _, k := range kids {
			if child, ok := k.(map[string]any); ok {
				m.TaskLabels = append(m.TaskLabels, taskLabelFromRecord(child))
			}
		}
	}
	return m
}

